-- OBEC 2021 Arts P6 indicators
with seed(standard_code,code,name,seq,classification) as (values
('ศ 1.1','ARTS-P6-01','ระบุคู่สีตรงข้าม และอภิปรายเกี่ยวกับการใช้คู่สีตรงข้ามในการถ่ายทอดความคิดและอารมณ์',1,'must_know'),
('ศ 1.1','ARTS-P6-02','อธิบายหลักการจัดขนาดสัดส่วน ความสมดุลในการสร้างงานทัศนศิลป์',2,'should_know'),
('ศ 1.1','ARTS-P6-03','สร้างสรรค์งานทัศนศิลป์โดยใช้สีคู่ตรงข้ามหลักการจัดขนาดสัดส่วน และความสมดุล',3,'must_know'),
('ศ 1.1','ARTS-P6-04','สร้างงานทัศนศิลป์จากรูปแบบ ๒ มิติ เป็น ๓ มิติ โดยใช้หลักการของแสงเงาและน้ำหนัก',4,'must_know'),
('ศ 1.1','ARTS-P6-05','สร้างสรรค์งานปั้นโดยใช้หลักการเพิ่มและลด',5,'should_know'),
('ศ 1.1','ARTS-P6-06','สร้างสรรค์งานทัศนศิลป์โดยใช้หลักการของรูปและพื้นที่ว่าง',6,'should_know'),
('ศ 1.1','ARTS-P6-07','สร้างงานทัศนศิลป์เป็นแผนภาพ แผนผัง และภาพประกอบเพื่อถ่ายทอดความคิดหรือเรื่องราวเกี่ยวกับเหตุการณ์ต่าง ๆ',7,'should_know'),
('ศ 1.2','ARTS-P6-08','บรรยายบทบาทของงานทัศนศิลป์ที่สะท้อนชีวิตและสังคม',8,'must_know'),
('ศ 1.2','ARTS-P6-09','อภิปรายเกี่ยวกับอิทธิพลของความเชื่อ ความศรัทธาในศาสนาที่มีผลต่องานทัศนศิลป์ในท้องถิ่น',9,'should_know'),
('ศ 1.2','ARTS-P6-10','ระบุและบรรยายอิทธิพลทางวัฒนธรรมในท้องถิ่นที่มีผลต่อการสร้างงานทัศนศิลป์ของบุคคล',10,'must_know'),
('ศ 2.1','ARTS-P6-11','บรรยายเพลงที่ฟัง โดยอาศัยองค์ประกอบดนตรี และศัพท์สังคีต',11,'must_know'),
('ศ 2.1','ARTS-P6-12','จำแนกประเภท และบทบาทหน้าที่เครื่องดนตรีไทยและเครื่องดนตรีที่มาจากวัฒนธรรมต่าง ๆ',12,'must_know'),
('ศ 2.1','ARTS-P6-13','อ่าน เขียนโน้ตไทย และโน้ตสากล ทำนองง่าย ๆ',13,'should_know'),
('ศ 2.1','ARTS-P6-14','ใช้เครื่องดนตรีบรรเลงประกอบ การร้องเพลง ด้นสด ที่มีจังหวะและทำนองง่าย ๆ',14,'must_know'),
('ศ 2.1','ARTS-P6-15','บรรยายความรู้สึกที่มีต่อดนตรี',15,'must_know'),
('ศ 2.1','ARTS-P6-16','แสดงความคิดเห็นเกี่ยวกับทำนอง จังหวะ การประสานเสียง และคุณภาพเสียงของเพลงที่ฟัง',16,'must_know'),
('ศ 2.2','ARTS-P6-17','อธิบายเรื่องราวของดนตรีไทยในประวัติศาสตร์',17,'must_know'),
('ศ 2.2','ARTS-P6-18','จำแนกดนตรีที่มาจากยุคสมัยที่ต่างกัน',18,'must_know'),
('ศ 2.2','ARTS-P6-19','อภิปรายอิทธิพลของวัฒนธรรมต่อดนตรีในท้องถิ่น',19,'must_know'),
('ศ 3.1','ARTS-P6-20','สร้างสรรค์การเคลื่อนไหวและการแสดงโดยเน้นการถ่ายทอดลีลา หรืออารมณ์',20,'should_know'),
('ศ 3.1','ARTS-P6-21','ออกแบบเครื่องแต่งกาย หรืออุปกรณ์ประกอบการแสดงอย่างง่าย ๆ',21,'must_know'),
('ศ 3.1','ARTS-P6-22','แสดงนาฏศิลป์และละครง่าย ๆ',22,'should_know'),
('ศ 3.1','ARTS-P6-23','บรรยายความรู้สึกของตนเองที่มีต่องานนาฏศิลป์และการละครอย่างสร้างสรรค์',23,'should_know'),
('ศ 3.1','ARTS-P6-24','แสดงความคิดเห็นในการชมการแสดง',24,'must_know'),
('ศ 3.1','ARTS-P6-25','อธิบายความสัมพันธ์ระหว่างนาฏศิลป์และการละครกับสิ่งที่ประสบในชีวิตประจำวัน',25,'must_know'),
('ศ 3.2','ARTS-P6-26','อธิบายสิ่งที่มีความสำคัญต่อการแสดงนาฏศิลป์และละคร',26,'must_know'),
('ศ 3.2','ARTS-P6-27','ระบุประโยชน์ที่ได้รับจากการแสดงหรือการชมการแสดงนาฏศิลป์และละคร',27,'should_know')
), subj as (select t.id topic_id,t.code standard_code from learning_subjects s join learning_skills sk on sk.subject_id=s.id join learning_topics t on t.skill_id=sk.id where s.code='ARTS' and sk.code='ARTS'), ins as (insert into learning_objectives(topic_id,code,name,sequence_no) select subj.topic_id,seed.code,seed.name,seed.seq from seed join subj using(standard_code) on conflict(topic_id,code) do update set name=excluded.name,sequence_no=excluded.sequence_no returning id,code) insert into learning_objective_alignments(objective_id,curriculum_id,grade_level_id,required,indicator_classification) select o.id,c.id,g.id,(seed.classification='must_know'),seed.classification from seed join ins o on o.code=seed.code join learning_curricula c on c.code='TH-BASIC-CORE-2008-2017' join learning_grade_levels g on g.curriculum_id=c.id and g.code='P6' on conflict(objective_id,curriculum_id,grade_level_id) do update set required=excluded.required,indicator_classification=excluded.indicator_classification;